{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret udpeger Uddannelses- og Forskningsstyrelsen i stedet for Udbetaling Danmark, selv om kilderne siger Udbetaling Danmark. Det angiver ikke de fire eksempelgrupper fra vejledningen, men opfinder egne eksempler, fx 'mulighed for at arbejde ved siden af studiet'. Det siger heller ikke, at betingelsen er 'i særlige tilfælde'. Det tilføjer, at ansøger kan spørge om, hvem der betaler, men nævner ikke, at Udbetaling Danmark betaler. Den kernefejl og de manglende elementer er væsentlige."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element, 'i særlige tilfælde' når art og grad ikke er tilstrækkeligt beskrevet, er kun delvist med: svaret nævner utilstrækkelige oplysninger, men ikke 'særlige tilfælde' og ikke art og grad. Det andet kritiske element mangler helt, for ingen af de fire eksempelgrupper gengives. Svaret nævner kun funktionsevne, varighed/ændring og arbejdsevne, som ikke svarer til grupperne."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret forsøger at besvare, hvornår der kan bedes om en erklæring. Det afviser dog spørgsmålets myndighed (Udbetaling Danmark) og erstatter vejledningens konkrete situationer med generiske eksempler. Det besvarer derfor ikke de væsentlige dele af spørgsmålet korrekt."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse, vejledning eller lov."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer væsentligt indhold uden støtte i materialet. Det peger på Uddannelses- og Forskningsstyrelsen som myndighed. Det opfinder eksempler som arbejdsmulighed ved siden af studiet. Det tilføjer, at myndigheden 'bør kunne forklare', hvad der mangler. Det foreslår, at ansøger kan bede om skriftlig begrundelse. Det siger, at sagen kan afgøres på det foreliggende grundlag og føre til afslag. Det antyder, at ansøger kan skulle bestille erklæringen selv."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke 'i særlige tilfælde'. Det bevarer heller ikke 'stor tvivl' eller 'mangelfulde' i de fire eksempelgrupper, som ikke gengives. Det siger rigtigt, at ikke alle ansøgere skal have en erklæring, men det er ikke nok."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: erklæring ved utilstrækkelige oplysninger, ikke alle ansøgere, og konsekvenser ved manglende medvirken. Det er ingen indre modsigelse, selv om forudsætningerne er forkerte."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er delvist rigtig med 'kan bede om' og 'ikke alle ansøgere skal'. Svaret gør dog vejledningens 'anmoder, hvis' til skønsmæssige formuleringer som 'bør' og 'kan være nødvendigt'. Det fjerner 'i særlige tilfælde'. Det vender også ansvar og betaling til et spørgsmål, hvor kilden siger, at Udbetaling Danmark betaler."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret siger, at myndigheden kan bede om en erklæring, når oplysningerne ikke er tilstrækkelige. Det mangler 'i særlige tilfælde', art og grad af funktionsnedsættelsen og alle fire eksempelgrupper. Det nævner desuden en forkert myndighed."
    }
  },
  "overall_notes": "Svaret er uden kildehenvisninger og udpeger en forkert myndighed. Det udelader de fire eksempelgrupper og 'i særlige tilfælde', og det tilføjer ustøttede regler og praktiske råd. Kun det generelle princip, at en erklæring ikke kræves i alle sager, og at den kan bruges ved utilstrækkelig dokumentation, svarer nogenlunde til kilden."
}

